    def __init__(self):
        """
        Initialize NumberWordFormatter object.
        """
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]



    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        """
        # Check if the number is an integer or a float
        if isinstance(x, int):
            # Convert the integer part of the number into words format
            integer_part = self.format_string(x)
            result = integer_part + " ONLY"
        elif isinstance(x, float):
            # Split the float number into integer and decimal parts
            integer_part, decimal_part = str(x).split(".")
            # Convert the integer part into words format
            integer_part = self.format_string(int(integer_part))
            # Convert the decimal part into words format
            decimal_part = self.format_string(int(decimal_part))
            result = integer_part + " AND " + decimal_part + " ONLY"
        else:
            result = "Invalid input. Please provide an integer or a float."

        return result


    def format_string(self, x):
        result = []
        num = int(x)

        if num == 0:
            result.append("ZERO")
            return " ".join(result)

        num_str = str(num)
        length = len(num_str)

        for i, digit in enumerate(num_str):
            if digit != "0":
                digit = int(digit)
                position = length - i

                if position == 1:
                    result.append(self.NUMBER[digit])
                elif position == 2:
                    if digit == 1:
                        result.append(self.NUMBER_TEEN[int(num_str[i+1])])
                        break
                    else:
                        result.append(self.NUMBER_TEN[digit-1])
                elif position == 3:
                    result.append("HUNDRED")
                    result.append(self.NUMBER[digit])

        if length > 3:
            result.append(self.parse_more(length - 3))

        result.append("ONLY")

        return " ".join(result)


    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        :param s: str, the two-digit number
        :return: str, the number in words format
        """
        tens_digit = int(s[0])
        ones_digit = int(s[1])

        if tens_digit == 1:
            return self.NUMBER_TEEN[ones_digit]
        elif tens_digit == 0:
            return self.NUMBER[ones_digit]
        else:
            return self.NUMBER_TEN[tens_digit - 1] + " " + self.NUMBER[ones_digit]


    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        :param s: str, the three-digit number
        :return: str, the number in words format
        """
